import cats.effect.{Resource, Sync}
import skunk.Session
import skunk.codec.all._
import skunk.implicits._
import grackle._
import grackle.Predicate._
import grackle.Query._
import grackle.QueryCompiler._
import grackle.Value._
import grackle.skunk._
import grackle.syntax._

trait SubscriptionMapping[F[_]] extends SkunkMapping[F] {
  val schema =
    schema"""
      type Query        { city(id: Int!): City }
      type Subscription { channel: City! }
      type City    { name: String!, country: Country!, population: Int! }
      type Country { name: String!, cities: [City!]! }
    """

  object country extends TableDef("country") {
    val code = col("code", bpchar(3)); val name = col("name", text)
  }
  object city extends TableDef("city") {
    val id = col("id", int4); val countrycode = col("countrycode", bpchar(3))
    val name = col("name", text); val population = col("population", int4)
  }

  val QueryType        = schema.ref("Query")
  val SubscriptionType = schema.ref("Subscription")
  val CountryType      = schema.ref("Country")
  val CityType         = schema.ref("City")

  val typeMappings = List(
    ObjectMapping(QueryType, List(SqlObject("city"))),
    ObjectMapping(CountryType, List(
      SqlField("code", country.code, key = true, hidden = true),
      SqlField("name", country.name),
      SqlObject("cities", Join(country.code, city.countrycode)))),
    ObjectMapping(CityType, List(
      SqlField("id", city.id, key = true, hidden = true),
      SqlField("countrycode", city.countrycode, hidden = true),
      SqlField("name", city.name),
      SqlField("population", city.population),
      SqlObject("country", Join(city.countrycode, country.code)))),
    ObjectMapping(SubscriptionType, List(
      // each Postgres NOTIFY on city_channel carries a city id;
      // build a child query that fetches that one city.
      RootStream.computeChild("channel")((child, _, _) =>
        for {
          s  <- fs2.Stream.resource(pool)
          id <- s.channel(id"city_channel").listen(256).map(_.value.toInt)
        } yield Unique(Filter(Eql(CityType / "id", Const(id)), child)).success)))
  )

  override val selectElaborator = SelectElaborator {
    case (QueryType, "city", List(Binding("id", IntValue(id)))) =>
      Elab.transformChild(child => Unique(Filter(Eql(CityType / "id", Const(id)), child)))
  }
}

object SubscriptionMapping extends SkunkMappingCompanion {
  def mkMapping[F[_]: Sync](pool: Resource[F, Session[F]], monitor: SkunkMonitor[F]): Mapping[F] =
    new SkunkMapping[F](pool, monitor) with SubscriptionMapping[F]
}

// Driving it (from the skunk SubscriptionSuite):
val query = """
  subscription { channel { name country { name } } }
"""
val prog: IO[List[Json]] =
  for {
    fi <- mapping.compileAndRunSubscription(query).take(2).compile.toList.start
    _  <- IO.sleep(1.second)                  // race: let the listener attach first
    _  <- pool.use { s =>
            val ch = s.channel(id"city_channel").contramap[Int](_.toString)
            List(101, 102, 103).traverse_(ch.notify)
          }
    out <- fi.join
    js  <- out.embedNever
  } yield js

import grackle.circe.CirceMapping  // brings CirceMappingRootStreamSyntax into scope
import io.circe.Json

// Inside a CirceMapping[F], on the Subscription type:
ObjectMapping(SubscriptionType, List(
  RootStream.computeJson("events")((path, env) =>
    someEventStream.map(json => Result(json)))   // Stream[F, Result[Json]]
))
// or, for an encodable type A with an io.circe.Encoder[A]:
ObjectMapping(SubscriptionType, List(
  RootStream.computeEncodable("events")((path, env) =>
    someEventStream.map(a => Result(a)))          // Stream[F, Result[A]]
))
